SELECT r.id, r.conversation_id, r.provider, r.mode, r.copy_mode, r.status, r.turn_id, r.message_id, r.payload_id, r.container_id, r.provider_file_id, r.filename, r.mime_type, r.size_bytes, r.checksum, r.error_message, r.expires_at, r.created_at, r.updated_at FROM (SELECT t.* FROM  (SELECT 0 AS should_delete, `id`, `conversation_id`, `turn_id`, `message_id`, `provider`, `mode`, `copy_mode`, `status`, `payload_id`, `container_id`, `provider_file_id`, `filename`, `mime_type`, `size_bytes`, `checksum`, `error_message`, `expires_at`, `created_at`, `updated_at` FROM generated_file)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)